/// <summary>
/// the <C>METPickupAdviceReportContract</C> class used as data contract class to run the pickup advice report
/// </summary>
[DataContractAttribute]

class METPickupAdviceReportContract extends METCommonReportContract
{
    SalesReturnItemNum      rmaNumber;

}

Method.Source:
/// <summary>
/// parm method to get set SalesReturnItemNum.
/// </summary>
/// <param name = "_rmaNumber">SalesReturnItemNum</param>
/// <returns>SalesReturnItemNum</returns>
[
    DataMemberAttribute('RMANumber'),
    SysOperationLabelAttribute('RMA number')
]
public SalesReturnItemNum parmRMANumber(SalesReturnItemNum _rmaNumber  = rmaNumber)
{
    rmaNumber   =   _rmaNumber;
    return  rmaNumber;
}
